float4 frag(UPEInput i)
{
    float life = 1.0 - i.color.a;
    float er = saturate((life - _ErodeStart) / max(1.0 - _ErodeStart, 0.001));

    // ---------- mod 0: kılıç aurası (s kabzadan uca, w bıçağa dik) ----------
    // bıçağın üstü yumuşak beyaz iç parlama (ortada düz, dışa söner); fırça dilleri _Gap'ten dışarı çıkar
    float s = lerp(i.uv.y, 1.0 - i.uv.y, _FlipS);
    float w = (i.uv.x - 0.5) * _Aspect;
    float aw = abs(w);
    float side = step(0.0, w);
    float t = i.time * _Flow;
    float env = sqrt(saturate(s / 0.06)) * saturate((1.0 - s) / 0.3);
    float tg = vnoise(float2(s * _Tongues - t, side * 17.0 + 3.0));
    float tg2 = vnoise(float2(s * _Tongues * 2.3 - t * 1.4, side * 5.0 + 11.0));
    float tongue = pow(saturate(tg * 0.8 + tg2 * 0.4), 1.8);
    float hw = _Gap * env + _Width * 0.5 * env * (0.06 + 0.94 * tongue);
    float grow = lerp(1.0, saturate(life * 1.12), _Grow);
    float front = grow * 1.08 - 0.04 + (vnoise(float2(w * 9.0, t)) - 0.5) * 0.08;
    float shown = AASTEP(s, front);
    float dEdge = hw - aw;
    float aBody = AASTEP(0.0, dEdge);
    float fib = vnoise(float2(w * _Fiber, s * 6.0 - t * 2.0));
    aBody *= AASTEP((aw / max(hw, 0.0001)) * _Dry - 0.35, fib);
    aBody *= smoothstep(_Gap * 0.5, _Gap * 1.5, aw) * shown;
    float inkB = 1.0 - AASTEP(hw * _InkWidth, dEdge);
    float shadowB = AASTEP(_ShadowBand, aw / max(hw, 0.0001));
    float glow = (1.0 - smoothstep(_Gap * 0.45 * env, _Gap * 1.7 * env, aw)) * saturate(env * 1.6) * shown;
    float3 cB = lerp(_BodyColor.rgb, _ShadowColor.rgb, shadowB);
    cB = lerp(cB, _InkColor.rgb, inkB);
    cB = lerp(cB, _CoreColor.rgb, glow);
    float aB = max(aBody, glow * _GlowAlpha);

    // ---------- mod 1: enso ----------
    float2 q = (i.uv - 0.5) * 2.0;
    float r = length(q);
    float ang = atan2(q.y, q.x);
    float u = frac((ang + PI * 0.5) / (2.0 * PI) + 0.5);
    float arc = 0.92;
    float ua = u / arc;
    float inArc = step(u, arc);
    float reveal = saturate(life / max(_Reveal, 0.001));
    float th = _Width * 0.5 * (0.55 + 0.45 * vnoise(float2(ua * 7.0, 1.7))) * sqrt(saturate(ua / 0.06)) * pow(saturate((1.0 - ua) / 0.5), 0.7);
    float R = 0.72 + 0.05 * vnoise(float2(ua * 3.0, 4.2));
    float dRing = th - abs(r - R);
    float aRing = AASTEP(0.0, dRing) * inArc;
    float fibR = vnoise(float2((r - R) * _Fiber, ua * 9.0));
    aRing *= AASTEP(ua, reveal);
    aRing *= AASTEP((1.0 - ua) * _Dry * 0.6 - 0.25, fibR);
    aRing *= AASTEP(er * 1.05, ua * 0.85 + fibR * 0.15);
    float inkR = 1.0 - AASTEP(th * _InkWidth, dRing);
    float shadowR = AASTEP(_ShadowBand, abs(r - R) / max(th, 0.0001)) * step(R, r);
    float coreR = AASTEP(abs(r - R), th * (0.25 + _Flash * 0.5 * saturate(1.0 - life / 0.2)));
    float3 cR = lerp(_BodyColor.rgb, _ShadowColor.rgb, shadowR);
    cR = lerp(cR, _CoreColor.rgb, coreR);
    cR = lerp(cR, _InkColor.rgb, inkR * (1.0 - coreR));

    // ---------- mod 2: dört köşeli fırça yıldızı ----------
    float2 pa = abs(q);
    float lob = vnoise(float2(ang * 2.0, 6.1));
    float st = sqrt(pa.x) + sqrt(pa.y);
    float dS = (0.92 + 0.08 * lob) - st;
    float aS = AASTEP(0.0, dS);
    float holes = vnoise(q * 6.0 + float2(4.0, 9.0));
    aS *= AASTEP(er * 1.1 - 0.05, holes * 0.55 + 0.45 * (1.0 - r));
    float inkS = 1.0 - AASTEP(0.07 + 0.05 * lob, dS);
    float coreS = AASTEP(0.16 - _Flash * 0.1 * saturate(1.0 - life / 0.25), dS);
    float3 cS = lerp(_BodyColor.rgb, _CoreColor.rgb, coreS);
    cS = lerp(cS, _InkColor.rgb, inkS * (1.0 - coreS));

    float m1 = step(0.5, _Mode) * (1.0 - step(1.5, _Mode));
    float m2 = step(1.5, _Mode);
    float3 c = lerp(lerp(cB, cR, m1), cS, m2) * i.color.rgb;
    float a = lerp(lerp(aB, aRing, m1), aS, m2);
    return float4(c, a);
}
